import { forwardRef } from "react";
import type { ComponentPropsWithoutRef } from "react";
import { cn } from "@/lib/utils";

const sizeMap = {
  xs: { px: 12, thickness: 1.5, inset: 0.9 },
  sm: { px: 14, thickness: 2, inset: 1.05 },
  md: { px: 16, thickness: 2, inset: 1.2 },
  lg: { px: 20, thickness: 2, inset: 1.5 },
};

const colorClasses = {
  gray: "text-ink-gray-8",
  red: "text-ink-red-7",
};

type SpinnerSize = keyof typeof sizeMap;
type SpinnerTheme = keyof typeof colorClasses;

export type SpinnerProps = Omit<ComponentPropsWithoutRef<"svg">, "color"> & {
  /** Diameter: xs 12px, sm 14px, md 16px, lg 20px. */
  size?: SpinnerSize;
  /** Fixed color. Omit to inherit the current text color. */
  theme?: SpinnerTheme;
  /** Draws a faint full-circle track behind the arc. */
  track?: boolean;
};

export const Spinner = forwardRef<SVGSVGElement, SpinnerProps>(
  ({ className, size, theme, track = false, style, ...props }, ref) => {
    const dimensions = size ? sizeMap[size] : undefined;
    const spinnerStyle = dimensions
      ? {
          width: `${dimensions.px}px`,
          height: `${dimensions.px}px`,
          "--spinner-thickness": `${dimensions.thickness}px`,
          "--spinner-mask-thickness": `${dimensions.thickness}px`,
          "--spinner-inset": `${dimensions.inset}px`,
        }
      : {};
    const rootStyle = { ...spinnerStyle, ...style };

    return (
      <svg
        ref={ref}
        width="16"
        height="16"
        role="status"
        aria-label="Loading"
        className={cn(
          "espresso-spinner inline-block shrink-0",
          theme && colorClasses[theme],
          track && "espresso-spinner--track",
          className,
        )}
        style={rootStyle}
        {...props}
      />
    );
  },
);

Spinner.displayName = "Spinner";

/* Spinner paints a rotating conic-gradient comet inside a masked ring.
   The gradient angle is registered so it can interpolate smoothly. */
@property --spinner-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.espresso-spinner {
  --spinner-thickness: 14.7%;
  --spinner-mask-thickness: 29.4%;
  --spinner-inset: 7.5%;
  --spinner-paint-size: calc(100% - 2 * var(--spinner-inset));
  --spinner-track-color: transparent;
  background-image:
    radial-gradient(
      calc(var(--spinner-thickness) / 2) calc(var(--spinner-thickness) / 2) at
        calc(50% + (50% - var(--spinner-thickness) / 2) * sin(var(--spinner-angle)))
        calc(50% - (50% - var(--spinner-thickness) / 2) * cos(var(--spinner-angle))),
      currentColor 92%,
      transparent
    ),
    conic-gradient(from var(--spinner-angle), transparent 32%, currentColor 92%, currentColor 100%),
    linear-gradient(var(--spinner-track-color), var(--spinner-track-color));
  background-size: var(--spinner-paint-size) var(--spinner-paint-size);
  background-position: center;
  background-repeat: no-repeat;
  -webkit-mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  animation: espresso-spinner-rotate 0.7s linear infinite;
}

.espresso-spinner--track {
  --spinner-track-color: color-mix(in srgb, currentColor 15%, transparent);
}

@keyframes espresso-spinner-rotate {
  to {
    --spinner-angle: 360deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .espresso-spinner {
    animation-duration: 1.6s;
  }
}
